<?php
$root=$argv[1];$stage=$argv[2];require $root.'/vendor/autoload.php';require $stage.'/app/Services/AdminPdvService.php';$app=require $root.'/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use Illuminate\Support\Facades\{DB,Schema,Queue,Mail,Http};use Illuminate\Database\Schema\Blueprint;use App\Models\{User,TagPurchase,Shipment};use App\Services\AdminPdvService;
config(['database.default'=>'pdv_orders_memory','database.connections.pdv_orders_memory'=>['driver'=>'sqlite','database'=>':memory:','prefix'=>'','foreign_key_constraints'=>true],'cache.default'=>'array']);DB::setDefaultConnection('pdv_orders_memory');if(DB::connection()->getDatabaseName()!==':memory:')throw new RuntimeException('Memory guard failed');Queue::fake();Mail::fake();Http::preventStrayRequests();
Schema::create('users',function(Blueprint $t){$t->id();$t->string('name');$t->string('email');$t->integer('type');$t->integer('pdv_id')->nullable();$t->integer('user_id_admin_pdv')->nullable();$t->softDeletes();$t->timestamps();});
Schema::create('vehicles',function(Blueprint $t){$t->id();foreach(['name','plate','color','year'] as $c)$t->string($c)->nullable();$t->timestamps();});
Schema::create('tags',function(Blueprint $t){$t->id();$t->string('name')->nullable();$t->string('slug')->nullable();$t->softDeletes();$t->timestamps();});
Schema::create('tags_purchases',function(Blueprint $t){$t->id();foreach(['user_id','vehicle_id','tag_id'] as $c)$t->integer($c)->nullable();$t->json('delivery')->nullable();$t->json('pickup_point')->nullable();$t->string('mp_payment_id')->nullable();$t->string('mp_payment_status')->nullable();$t->integer('status')->default(0);$t->decimal('price_total',8,2)->default(29.90);$t->integer('qty')->default(1);$t->softDeletes();$t->timestamps();});
Schema::create('shipments',function(Blueprint $t){$t->id();$t->integer('tag_purchase_id');$t->string('carrier')->nullable();$t->integer('status')->default(0);$t->string('tracking_code')->nullable();$t->timestamp('delivered_at')->nullable();$t->softDeletes();$t->timestamps();});
$n=0;$ok=function($v,$m)use(&$n){if(!$v)throw new RuntimeException($m);$n++;};$mkUser=fn($name,$type,$point=null,$creator=null)=>User::create(['name'=>$name,'email'=>$name.'@example.test','type'=>$type,'pdv_id'=>$point,'user_id_admin_pdv'=>$creator]);
$a=$mkUser('qa-a',2,10);$b=$mkUser('qa-b',2,20);$no=$mkUser('qa-no-point',2);$direct=$mkUser('qa-direct',3);$client=$mkUser('qa-origin',3,null,$a->id);$external=$mkUser('qa-external',3,null,$b->id);
$mkOrder=fn($user,$point,$delivery=null)=>TagPurchase::create(['user_id'=>$user->id,'pickup_point'=>$point===null?null:['id'=>$point,'label'=>'QA point'],'delivery'=>$delivery,'mp_payment_id'=>'qa-payment','mp_payment_status'=>'pending']);
$own=$mkOrder($client,null,['city'=>'QA']);$numeric=$mkOrder($direct,10);$string=$mkOrder($direct,'10');$foreign=$mkOrder($external,20);$invalid=$mkOrder($direct,10,['city'=>'QA']);$none=$mkOrder($direct,null);$zero=$mkOrder($direct,0);$both=$mkOrder($client,10);
$svc=new AdminPdvService;$ids=$svc->orders($a)->getCollection()->pluck('id')->all();$expected=[$own->id,$numeric->id,$string->id,$both->id];sort($ids);sort($expected);$ok($ids===$expected,'origin and selected numeric/string point visible only once');
$ok(!in_array($foreign->id,$ids),'other PDV order hidden');$ok(!in_array($invalid->id,$ids),'home delivery cannot leak through stale pickup field');$ok(!in_array($none->id,$ids),'unassigned orders hidden');$ok(!in_array($zero->id,$ids),'point zero hidden');$ok($svc->orders($no)->total()===0,'admin without point does not gain pickup access');
$ok($svc->orders($a,'qa-direct')->total()===2,'search works inside allowed scope');$ok($svc->orders($a,'qa-external')->total()===0,'search cannot escape point scope');$ok($svc->orders($b)->getCollection()->pluck('id')->all()===[$foreign->id],'second point isolated');
$shipment=Shipment::create(['tag_purchase_id'=>$numeric->id,'carrier'=>'retirada','status'=>0]);$svc->updateOrderStatus($a,$numeric->id,['status'=>1]);$ok($shipment->fresh()->status==1,'selected PDV can prepare pickup');$ok($numeric->fresh()->mp_payment_status==='pending','shipment change cannot approve payment');
try{$svc->updateOrderStatus($b,$numeric->id,['status'=>1]);throw new RuntimeException('Foreign point write allowed');}catch(Illuminate\Database\Eloquent\ModelNotFoundException $e){$ok(true,'foreign point write rejected');}
try{$svc->updateOrderStatus($a,$numeric->id,['status'=>4]);throw new RuntimeException('Manual pickup delivery allowed');}catch(Illuminate\Validation\ValidationException $e){$ok(isset($e->errors()['status']),'delivery requires QR verification');}
$ok($shipment->fresh()->status==1,'manual pickup attempt changes nothing');$shipment->update(['status'=>4]);try{$svc->updateOrderStatus($a,$numeric->id,['status'=>0]);throw new RuntimeException('Collected pickup reopened');}catch(Illuminate\Validation\ValidationException $e){$ok(true,'confirmed pickup cannot reopen');}
$ok($direct->fresh()->user_id_admin_pdv===null&&$direct->fresh()->pdv_id===null,'pickup never rewrites customer commercial attribution');
$numeric->delete();$ok(!$svc->orders($a)->getCollection()->contains('id',$numeric->id),'deleted order hidden');Mail::assertNothingSent();$ok(true,'no email sent');echo 'PASS '.$n.' isolated PDV order scope checks; memory only, fake queue/mail, no payment calls.'.PHP_EOL;
